 1	method rev(a : array<int>)
 2	    requires a != null;
 3	    modifies a;
 4	    ensures forall k :: 0 <= k < a.Length ==> a[k] == old(a[(a.Length - 1) - k]);
 5	{
 6	    var i := 0;
 7	    while (i < a.Length - 1 - i)
 8	        invariant 0 <= i <= a.Length/2;
 9	        invariant forall k :: 0 <= k < i || a.Length - 1 - i < k <= a.Length - 1 ==> a[k] == old(a[a.Length - 1 - k]); //The reversed region contains the opposing values
10	    {
11	        a[i], a[a.Length - 1 - i] := a[a.Length - 1 - i], a[i];
12	        i := i + 1;
13	    }
14	}

